// DDA test implementation for area skipping via texture MipMaps.
// Since I could only find talks describing this technique without any implementations the algorithm might have quite a bit of room for improvement.
// The reason of using this approach over quadtree or sdf is the uncomplex and fast MipMap recalculation making dynamic changes very affordable.

const float RENDER_SCALE = 0.15;
const int MAX_STEPS = 32;
const float EPSILON = 0.001;

const int MIP_LEVELS = 4;
const int MAX_MIP = MIP_LEVELS - 1;
const vec2[MIP_LEVELS] MIP_STEP = vec2[MIP_LEVELS] ( vec2(1.0, 1.0), vec2(2.0, 0.5), vec2(4.0, 0.25), vec2(8.0, 0.125) );

struct MipRay {
    vec2 origin;
    vec2 inverse;
    float tMax;
    float mipToWorld;
    float worldToMip;
};


////////[ Drawing ]//////////////////////////////////////////////////////////////

float grid(vec2 coord, float size) {
    vec2 side = abs(fract(coord / size) - 0.5);
    side = smoothstep(0.5 - (0.15 / size), 0.495, side);

    return max(side.x, side.y);
}

float line(vec2 p0, vec2 p1, float r, vec2 wPos) {
    vec2 dir = p1 - p0;

    dir = normalize(dir);
    vec2 lhs = wPos - p0;

    float dotP = dot(lhs, dir);

    vec2 pLine = p0 + dir * dotP;
    float dist = dotP > 0.0 && dotP < distance(p0, p1) ? distance(pLine, wPos) : 1.0; 

    return step(dist, r);
}

bool box(vec2 min, vec2 size, vec2 pos) {
    vec2 max = min + size;

    return pos.x >= min.x && pos.x <= max.x && pos.y >= min.y && pos.y <= max.y;
}

bool circle(vec2 cen, float r, vec2 pos) {
    return distance(pos, cen) < r;
}


////////[ Raymarching ]//////////////////////////////////////////////////////////////

MipRay CreateRay(vec2 origin, vec2 direction, int mip) {
    MipRay r;

    r.mipToWorld = MIP_STEP[mip].x;
    r.worldToMip = MIP_STEP[mip].y;

    r.origin = origin * r.worldToMip;
    r.inverse = (1.0 / direction) * r.mipToWorld;
    r.tMax = 0.0;

    return r;
}

float obstacle(vec2 pos, int mip) {
    // Fake MipMap levels are written into rgba channels
    return texelFetch(iChannel1, ivec2(pos), 0)[mip];
}

float march(vec2 p0, vec2 p1, vec2 wPos) {
    vec2 rd = normalize(p1 - p0);
    vec2 rSgn = sign(rd);
    vec2 hSgn = rSgn * 0.5 + 0.5;

    int mip = MAX_MIP;

    // Per mip level data
    MipRay[MIP_LEVELS] rays;    
    for(int i = 0; i < MIP_LEVELS; i++) {
        rays[i] = CreateRay(p0, rd, i);
    }

    float maxDist = distance(p0, p1);
    rays[MAX_MIP].tMax = maxDist;

    MipRay ray = rays[mip];

    float tMin = 0.0;
    vec2 pos = p0;
    vec2 grid = floor(pos * ray.worldToMip);            
    vec2 edge = (grid - ray.origin + hSgn) * ray.inverse;  
    float hit = -1.0;

    for (int i = 0; i < MAX_STEPS; i++) {
        ray = rays[mip];    
        grid = floor(pos * ray.worldToMip);

        if(obstacle(grid, mip) <= 0.5) {
            // Step down mip level and break at lowest level
             if(mip == 0) {
                if(box(grid * ray.mipToWorld, vec2(ray.mipToWorld), wPos)) hit = max(hit, 1.0);
                break;                
            }

            mip--;                                
            i--; // Should this be allowed?

            // Mip change will occur at the border of the previous level
            rays[mip].tMax = tMin;

            continue;
        }

        // Due to mip level differences I have to recalculate edges per step?
        edge = (grid - ray.origin + hSgn) * ray.inverse;
        tMin = min(edge.x, edge.y);               
        pos = p0 + rd * (tMin + EPSILON);

        // Can only go up one mip level at a time for now
        mip += tMin >= ray.tMax ? 1 : 0;

        // Draw box and intersections and check length
        hit = max(hit, box(grid * ray.mipToWorld, vec2(ray.mipToWorld), wPos) ? 0.0 : -1.0);

        if(tMin > maxDist) break;

        hit = max(hit, circle(pos, 0.35, wPos) ? 1.0 : -1.0);
    }

    // Calculate normal if needed
    // vec2 normal = step(edge.xy, edge.yx) * rSgn;

    return hit;
}


////////[ Main ]//////////////////////////////////////////////////////////////

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 pos = fragCoord.xy * RENDER_SCALE;

    float g = 0.0;
    float map = 0.0;

    for(int i = 0; i < 4; i++) {
        g += grid(pos, MIP_STEP[i].x);
        map += obstacle(pos * MIP_STEP[i].y, i) * 0.25;
    }

    // Grid + Map
    vec3 color = vec3((1.0 - g * 0.1) * map);

    // Fetch mouse start and end from buffer
    vec2 p0 = texelFetch(iChannel0, ivec2(0, 0), 0).xy;
    vec2 p1 = texelFetch(iChannel0, ivec2(0, 0), 0).zw;    

    color += line(p0, p1, 0.1, pos) * -0.4;

    // Raymarch
    float hit = march(p0, p1, pos);

    // Draw hit
    if(hit >= 0.0) {
        vec3 hitColor = mix(vec3(0.0, 0.75, 1.0), vec3(1.0, 0.0, 0.0), min(hit, 1.0));
        color = mix(color, hitColor, hit * 0.5 + 0.25);
    }

    // Draw start pos
    if(circle(p0, 0.4, pos)) color = vec3(0.0, 0.25, 1.0);

    fragColor = vec4(color, 1.0);
}

// Buffer to hold mouse start and end point

const float RENDER_SCALE = 0.15;

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    ivec2 address = ivec2(fragCoord); // Sould be sampled at 0 0

    fragColor = vec4(55.5, 20.5, 175.0, 80.0);

    if (iFrame > 0) { 
        vec2 mPos = iMouse.xy * RENDER_SCALE;

        fragColor = texelFetch(iChannel0, address, 0);

        if(iMouse.w > 0.0) {
            fragColor.xy = mPos;
        }

        if(iMouse.z > 0.0) {
            fragColor.zw = mPos;
        }
    }
}

// Obstacle mip mapping in a single fragment. Values are 0 for solid and 1 for air.
// Single pass due to buffer limitation but should be done in multiple steps. (best via a compute shader)

float fetch(ivec2 pos) {
    // Set fixed cutoff to 0.5 and inverted for test lookup
    return 1.0 - floor(texelFetch(iChannel0, pos, 0).x + 0.5);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord){
    vec4 v = vec4(1.0);

    ivec2 p = ivec2(fragCoord);
    int x, y, m;

    // If a one of the four pixels of the previous mip is solid do the same with the new level
    for(y = 0; y < 8; y++) {
        for(x = 0; x < 8; x++) {       
            m = max(x, y);

            v.x = m >= 1 ? v.x : fetch(p);
            v.y = m >= 2 ? v.y : min(v.y, fetch(p * 2 + ivec2(x, y)));
            v.z = m >= 4 ? v.z : min(v.z, fetch(p * 4 + ivec2(x, y)));
            v.w = min(v.w, fetch(p * 8 + ivec2(x, y)));
        }
    }   

    fragColor = v;
}
